// Fills ~50% of the 2-hour windows (Mon-Fri, 08-18 America/New_York)
// for the next 14 calendar days, starting tomorrow. Deterministic per run date.
const ZONE = 'America/New_York';
const WINDOW_STARTS = [8, 10, 12, 14, 16];
const DAYS_AHEAD = 14;
const FILL_RATIO = 0.5;

let seed = Number(DateTime.now().setZone(ZONE).toFormat('yyyyLLdd'));
function rand() { seed = (seed * 1103515245 + 12345) % 2147483648; return seed / 2147483648; }
function pick(list) { return list[Math.floor(rand() * list.length)]; }

const firstNames = ['James', 'Maria', 'Robert', 'Linda', 'Michael', 'Patricia', 'David', 'Jennifer', 'Daniel', 'Susan', 'Kevin', 'Angela', 'Brian', 'Nicole', 'Steven', 'Karen'];
const lastNames = ['Johnson', 'Garcia', 'Miller', 'Davis', 'Rodriguez', 'Wilson', 'Anderson', 'Thomas', 'Moore', 'Martin', 'Clark', 'Lewis', 'Walker', 'Hall'];
const streets = ['Maple Ave', 'Oak St', 'Pine Rd', 'Cedar Ln', 'Elm St', 'Birch Dr', 'Willow Way', 'Lakeview Blvd', 'Hillcrest Rd', 'Park Pl'];
const jobs = [
  ['refrigerator', 'not cooling, freezer still works'],
  ['refrigerator', 'leaking water under the unit'],
  ['dishwasher', 'not draining, water left at the bottom'],
  ['dishwasher', 'dishes come out dirty'],
  ['washer', 'will not spin'],
  ['washer', 'shaking loudly during spin cycle'],
  ['dryer', 'runs but does not heat'],
  ['dryer', 'drum not turning'],
  ['oven', 'not heating to set temperature'],
  ['range', 'one burner will not light'],
  ['microwave', 'turns on but does not heat']
];
const warrantyBrands = ['LG', 'Samsung', 'GE'];
const paidBrands = ['Whirlpool', 'Maytag', 'KitchenAid', 'Frigidaire', 'Bosch', 'Kenmore', 'LG', 'Samsung', 'GE'];

const rows = [];
const now = DateTime.now().setZone(ZONE);
let counter = 1;
for (let d = 1; d <= DAYS_AHEAD; d++) {
  const day = now.plus({ days: d }).startOf('day');
  if (day.weekday > 5) continue;
  for (const hour of WINDOW_STARTS) {
    if (rand() >= FILL_RATIO) continue;
    const isWarranty = rand() < 0.3;
    const brand = isWarranty ? pick(warrantyBrands) : pick(paidBrands);
    const job = pick(jobs);
    const name = pick(firstNames) + ' ' + pick(lastNames);
    const slotStart = day.set({ hour, minute: 0, second: 0, millisecond: 0 }).toISO({ suppressMilliseconds: true });
    rows.push({
      slot_start: slotStart,
      booking_id: 'SEED-' + String(counter++).padStart(3, '0'),
      title: (isWarranty ? 'Warranty' : 'Paid') + ' repair: ' + job[0] + ' (' + brand + ') — ' + name,
      customer_name: name,
      phone: '555-01' + String(Math.floor(rand() * 100)).padStart(2, '0'),
      service_address: (100 + Math.floor(rand() * 900)) + ' ' + pick(streets),
      appliance_type: job[0],
      brand: brand,
      issue_description: job[1],
      is_warranty: isWarranty,
      fee_accepted: !isWarranty,
      fee: isWarranty ? 'warranty: no fee' : '$99',
      created_at: now.toISO()
    });
  }
}
return rows.map(r => ({ json: r }));
